# owner: platform

from typing import Tuple, List
from collections import Counter

from hourglass.schedule import worker_minutes
from hourglass.models import Shift

WorkerRow = Tuple[str, int, int]


def check_shifts(shifts: List[Shift]) -> None:
    """Refuse an empty list or a blank worker name."""
    if not shifts:
        raise ValueError("no shifts to build from")
    if any(not shift.worker.strip() for shift in shifts):
        raise ValueError("a shift has a blank worker name")


def busiest_first(item: WorkerRow) -> Tuple[int, str]:
    """Most minutes first, with ties broken by name."""
    return (-item[2], item[0])


def worker_rows(shifts: List[Shift]) -> List[WorkerRow]:
    """Busiest first: (name, shift count, minutes)."""
    counts = Counter(shift.worker for shift in shifts)
    rows = [
        (name, counts[name], minutes)
        for name, minutes in worker_minutes(shifts).items()
    ]
    return sorted(rows, key=busiest_first)


def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker: name, shifts and hours."""
    check_shifts(shifts)
    return [
        f"{name}: {count} shifts, "
        f"{minutes / 60:.1f} hours"
        for name, count, minutes in worker_rows(shifts)
    ]
